    "correct": "(1)",
    "explanation": "<strong>【正解：(1)】</strong><br><br><strong>【解法の解説】</strong><br>C部門の貢献利益（300,000円）は、削減可能な個別固定費（200,000円）を100,000円上回っており、共通固定費の回収に100,000円貢献しています。<br>C部門を廃止すると、この100,000円の回収分が消失し、共通固定費200,000円は残るため、会社全体の営業利益は【￥100,000 減少】して悪化します。",
